  const BrandLayer(this.part, this.d, {this.stroke = 0, this.round = false, this.scale = 1, this.dx = 0, this.dy = 0});
  final BrandPart part;
  final String d;
  final double stroke;
  final bool round;
  final double scale;
  final double dx;
  final double dy;
}

/// A complete lockup: its box and its layers, painted in order.
class BrandArt {
  const BrandArt({required this.width, required this.height, required this.layers});
  final double width;
  final double height;
  final List<BrandLayer> layers;
}

